id #dcdccd;border-radius:8px}.plan-panel svg{width:100%;height:auto;max-height:850px}svg{width:100%;height:auto}.room-index{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0}.room-index a{background:#e7e8dc;padding:10px;text-decoration:none}.room-index b{margin-left:8px;color:#a47856}.gallery,.night-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}.gallery figure:first-child{grid-column:span 2}.room{padding:35px 0;border-top:1px solid #d8d8ca}.room-heading span{font-size:12px;letter-spacing:.05em;color:#a47354}.room-heading h3{font-size:30px;margin:8px 0}.room-heading p{color:#60725e}.room-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:30px;align-items:start}.room-grid figure{position:sticky;top:24px}.tradeoff{padding:10px 20px;border-right:3px solid #a47354;background:#ece5d8}.hold-link{display:inline-block;font-family:Arial,sans-serif;direction:ltr;font-size:11px;padding:2px 7px;margin:4px 1px;border:1px solid #b9c2b4;border-radius:4px;text-decoration:none}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.swatches div{background:#fcfaf5;border:1px solid #deded0;border-radius:6px;padding:16px}.swatches span{height:86px;border-radius:4px;display:block;box-shadow:inset 0 0 0 1px #293b3310}.swatches p{font-size:12px}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:30px}.three-col,.decision-grid,.visit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.decision-grid article,.visit-grid article{padding:20px;background:#fbf9f4;border:1px solid #deded1;border-radius:6px}.decision-grid h3{font-size:20px}.segmented,.hold-controls{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.segmented button,.hold-controls button{border:1px solid #98ab93;background:#f7f5ee;border-radius:3px;padding:5px 17px;color:#375448}.segmented .active,.hold-controls .active{background:#526d54;color:white}.night-pair{border:1px solid #d8dccd;padding:20px;background:#fcfaf4}.night-pair p{font-size:12px}.table-wrap{overflow:auto;margin:20px 0}table{border-collapse:collapse;width:100%;background:#fcfaf4;font-size:14px}th,td{padding:14px;text-align:right;border-bottom:1px solid #dedfd3;vertical-align:top}thead th{background:#dfe5d8;font-weight:600}th{font-weight:500}td input{min-width:90px;width:100%;border:1px solid #c2cdbd;padding:7px;background:white;border-radius:3px}#inventory{min-width:790px}#inventory small{display:block;font-size:11px;color:#72856f}details{margin:12px 0;padding:15px;background:#eeeee4;border:1px solid #d8ddcf;border-radius:4px}summary{cursor:pointer;font-size:15px}details p{font-size:14px}details svg{background:#fff;margin-top:18px}summary small{float:left;font-size:10px}.badge{display:inline-block;border:1px solid #abbbb0;border-radius:3px;padding:0 7px;font-size:11px}.hold-row[hidden]{display:none}pre{direction:ltr;text-align:left;overflow:auto;max-height:400px;font-size:11px;background:#f8f8f0;padding:12px;white-space:pre-wrap;overflow-wrap:anywhere}.primary{background:#526d54;color:white;border:0;border-radius:4px;padding:10px 20px}.small{font-size:12px}dialog{border:0;padding:12px;background:#f5f2eb;border-radius:8px;width:min(96vw,1450px);max-height:95vh;overflow:auto}dialog::backdrop{background:#15251eda}dialog button{float:left;padding:6px 20px;margin-bottom:10px;background:#526d54;color:white;border:0}footer{font-size:12px;color:#66776b;padding:24px}.footer-source{direction:ltr;text-align:left;font-family:monospace;overflow-wrap:anywhere}#hold-search{padding:5px 15px;border:1px solid #a8b9a0}ul,ol{padding-right:22px}li{margin-bottom:10px}@media(max-width:1050px){aside{position:sticky;top:0;width:100%;height:auto;padding:12px 18px;z-index:5}aside strong{font-size:18px;display:inline}aside small{display:none}aside nav{margin:8px 0 0;display:flex;gap:18px;overflow:auto;white-space:nowrap}aside a{padding:3px 0;border:0;font-size:12px}main{margin:0;padding:20px 5vw}section{scroll-margin-top:110px}.hero-grid,.room-grid{grid-template-columns:1fr}.room-grid figure{position:static}.three-col,.decision-grid,.visit-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.lead{font-size:20px}.gallery,.night-grid,.two-col,.three-col,.decision-grid,.visit-grid{grid-template-columns:1fr}.gallery figure:first-child{grid-column:auto}.swatches,.room-index{grid-template-columns:repeat(2,1fr)}.plan-panel{padding:8px}.room-heading h3{font-size:26px}h2{margin-bottom:20px}.stats b{font-size:27px}section{padding-bottom:35px}}@media print{aside,button,.hold-controls{display:none}main{margin:0;padding:0}details{break-inside:avoid}.room-grid,.hero-grid{grid-template-columns:1fr 1fr}.room-grid figure{position:static}.room{break-inside:avoid}section{padding:20px 0}img{max-height:400px;object-fit:contain}.table-wrap{overflow:visible}body{background:white}a{color:#33483d}}'''
script='''const ASSETS=__ASSETS__;document.querySelectorAll('[data-frame]').forEach(img=>{if(ASSETS[img.dataset.frame])img.src=ASSETS[img.dataset.frame];else img.alt+=' [missing capture]'});const modal=document.querySelector('dialog');document.querySelectorAll('[data-zoom]').forEach(b=>b.addEventListener('click',()=>{modal.querySelector('img').src=ASSETS[b.dataset.zoom];modal.showModal()}));document.querySelector('#close-zoom').addEventListener('click',()=>modal.close());document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{const key='SCENARIO-'+b.dataset.pair+(b.dataset.mode==='night'?'-night':'');document.querySelector('#pair-'+b.dataset.pair).src=ASSETS[key];b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b))}));document.querySelectorAll('[data-room]').forEach(x=>{const go=()=>document.querySelector('#room-'+x.dataset.room)?.scrollIntoView();x.addEventListener('click',go);x.addEventListener('keydown',ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();go()}})});let filter='ALL';const apply=()=>{const q=document.querySelector('#hold-search').value.toLowerCase();document.querySelectorAll('.hold-row').forEach(x=>x.hidden=(filter!=='ALL'&&x.dataset.priority!==filter)||!x.textContent.toLowerCase().includes(q))};document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));apply()}));document.querySelector('#hold-search').addEventListener('input',apply);document.querySelectorAll('a[href^="#G"]').forEach(a=>a.addEventListener('click',()=>{filter='ALL';document.querySelector('#hold-search').value='';apply();const t=document.querySelector(a.getAttribute('href'));if(t)t.open=true}));document.querySelector('#inventory-export').addEventListener('click',()=>{const rows=[['id','category','count','dimensions_mm','frequency','allocated_storage_id']];document.querySelectorAll('#inventory tbody tr').forEach(tr=>rows.push([tr.dataset.inventory,tr.querySelector('th').innerText,...[...tr.querySelectorAll('input')].map(x=>x.value)]));const csv='\\ufeff'+rows.map(r=>r.map(x=>'"'+x.replaceAll('"','""')+'"').join(',')).join('\\r\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Type-B-Owner-Inventory.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});'''.replace('__ASSETS__',json.dumps(assets,separators=(',',':')))
